int count_above_average(const int data[], int size)
{
    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += data[i];
    }
    double avg = sum / size;
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (data[i] > avg) {
            count++;
        }
    }
    return count;
}

