int max_row(const int grid[][5], int rows)
{
    int best = 0, best_sum = 0;
    for (int r = 0; r < rows; r++) {
        int sum = 0;
        for (int c = 0; c < 5; c++) sum += grid[r][c];
        if (r == 0 || sum > best_sum) {
            best = r;
            best_sum = sum;
        }
    }
    return best;
}

